/* MIT. End-to-end casts: source timing, live validation, resource atomicity and save isolation. */
#include <assert.h>
#include "save_store.h"
#include "developer.h"
static int clear(void*w,float x,float y,float a,float b){return a>8&&b>8&&a<3192&&b<3192;}
static int blocked(void*w,float x,float y,float a,float b){return 0;}
static void dummy(Combat*g,int i){CombatMob*m=&g->mobs[i];memset(m,0,sizeof(*m));m->enabled=m->training=1;m->kind=1;m->hp=m->testMaxHP=100000;m->x=m->homeX=g->x+8+i*8;m->y=m->homeY=g->y;m->attackAt=m->hurtAt=m->deadAt=-100;}
static void fresh(Combat*g,unsigned id){combat_init(g,1500,1500,clear,NULL);dev_class_preset(g,id==51?3:2);memset(g->mobs,0,sizeof(g->mobs));g->canAim=clear;g->peaceful=1;dummy(g,0);dummy(g,1);g->target=0;g->maxsp=g->sp=5000;}
static void finish(Combat*g){int n=0;while(combat_casting(g)){combat_tick(g,.05f,0,0);assert(++n<=250);}}
static void start(Combat*g,unsigned id){assert(skill_cast(g,id,g->x+8,g->y));assert(combat_casting(g));}
int main(void){Combat g;unsigned ids[]={3,9,21,22,23,24,29,30,31,49,51,67};int samples=0;
 for(unsigned j=0;j<sizeof(ids)/sizeof(*ids);j++)for(int rank=1;rank<=10;rank+=rank==1?4:5){unsigned id=ids[j];if((id==51||id==67)&&rank>1)continue;fresh(&g,id);g.ranks[skill_rank_index(id)]=rank;int cost=skill_cost(&g,id),sp=g.sp;float total=skill_cast_seconds(&g,id,rank);int oldhp=g.mobs[0].hp;start(&g,id);assert(fabsf(g.spellCastTotal-total)<.00001f&&g.sp==sp&&g.lastCast<0&&g.fxAt<0&&!g.autoAttack);int ticks=(int)ceilf(total/.05f-.0001f);for(int i=0;i<ticks-1;i++){combat_tick(&g,.05f,0,0);assert(combat_casting(&g)&&g.sp==sp&&g.mobs[0].hp==oldhp);}combat_tick(&g,.05f,0,0);assert(!combat_casting(&g)&&g.sp==sp-cost&&g.fxSkill==(int)id&&g.lastCast==g.time);assert(fabsf(g.castDelay-cast_timing(id)->delay[rank-1]/1000.f)<.0001f&&g.skillCD[id-1]==0);if(g.castDelay>0)assert(!skill_cast(&g,id,g.x+8,g.y));samples++;}
 /* Pre-renewal DEX multiplier and source rank curves, including true zero time. */
 int dexes[]={0,1,30,149,150,200};for(unsigned j=0;j<sizeof(ids)/sizeof(*ids);j++)for(unsigned k=0;k<sizeof(dexes)/sizeof(*dexes);k++){unsigned id=ids[j];fresh(&g,id);g.stats[4]=dexes[k];int rank=skill_rank(&g,id);float expected=cast_timing(id)->cast[rank-1]*fmaxf(0,150-dexes[k])/150000.f;assert(fabsf(skill_cast_seconds(&g,id,rank)-expected)<.00001f);int sp=g.sp,cost=skill_cost(&g,id);assert(skill_cast(&g,id,g.x+8,g.y));if(expected>.0001f){assert(combat_casting(&g));finish(&g);}else assert(!combat_casting(&g));assert(g.sp==sp-cost);samples++;}
 fresh(&g,3);g.stats[4]=20;float plain=skill_cast_seconds(&g,3,10);g.buffs[0]=100;g.buffLevels[0]=10;assert(skill_cast_seconds(&g,3,10)<plain);g.buffs[0]=0;g.jobId=5;g.concentrateLeft=100;g.concentrateRank=10;assert(skill_cast_seconds(&g,3,10)<plain);
 /* Every interruption releases resources and leaves no completion flash/cooldown. */
 for(int cause=0;cause<12;cause++){fresh(&g,3);int sp=g.sp;start(&g,3);switch(cause){case 0:combat_cancel(&g);break;case 1:combat_tick(&g,.05f,1,0);break;case 2:combat_ranged_hit(&g,1);break;case 3:g.silenceLeft=2;break;case 4:g.sitting=1;break;case 5:g.hideLeft=1;break;case 6:g.hp=0;break;case 7:g.jobId=3;break;case 8:g.mapId++;break;case 9:g.ranks[skill_rank_index(3)]--;break;case 10:*inventory_stack(&g,ITEM_ARROW)=inventory_weight_max(&g);break;case 11:g.mobs[0].hp=0;break;}combat_tick(&g,.05f,0,0);assert(!combat_casting(&g)&&g.sp==sp&&g.lastCast<0&&g.fxAt<0&&g.castDelay==0&&g.skillCD[2]==0);samples++;}
 /* Failed release must not redirect, spend SP/gems, or start a cast effect. */
 for(int cause=0;cause<7;cause++){unsigned id=cause>=4?49:3;fresh(&g,id);int gems=inventory_count(&g,ITEM_RED_GEM);start(&g,id);switch(cause){case 0:g.mobs[0].x=g.x+161;break;case 1:g.canAim=blocked;break;case 2:g.sp=skill_cost(&g,id)-1;break;case 3:g.mobs[0].life++;break;case 4:*inventory_stack(&g,ITEM_RED_GEM)=0;break;case 5:g.mobs[0].hidden=1;break;case 6:g.mobs[0].testTraits=3;break;}int sp=g.sp;finish(&g);assert(g.sp==sp&&g.lastCast<0&&g.fxAt<0&&g.mobs[1].hp==100000);if(cause!=4)assert(inventory_count(&g,ITEM_RED_GEM)==gems);samples++;}
 fresh(&g,3);start(&g,3);g.target=1;g.mobs[0].x=g.x+50;finish(&g);assert(g.mobs[0].hp<100000&&g.mobs[1].hp==100000&&g.fxX==g.x+50);
 fresh(&g,3);start(&g,3);assert(!skill_cast(&g,67,0,0));combat_attack(&g);assert(!g.autoAttack);g.pneuma[0]=(PneumaField){g.x,g.y,100};assert(!combat_ranged_hit(&g,10)&&combat_casting(&g));finish(&g);assert(g.mobs[0].hp<100000);
 /* Ground point remains fixed; placement/capacity are checked on release. */
 for(int cause=0;cause<3;cause++){fresh(&g,31);start(&g,31);if(cause==0){g.target=1;g.mobs[0].x+=32;}if(cause==1)g.canAim=blocked;if(cause==2)for(int i=0;i<3;i++){g.barriers[i].expires=100;g.barriers[i].x=g.x+200;g.barriers[i].y=g.y+200;g.barriers[i].hits[0]=g.barriers[i].hits[1]=g.barriers[i].hits[2]=10;}int sp=g.sp;finish(&g);if(cause==0)assert(g.sp==sp-40&&g.barriers[0].x==g.x+8);else assert(g.sp==sp&&g.lastCast<0);samples++;}
 /* Replacing a dead live mob slot cannot redirect an already pending cast. */
 fresh(&g,3);g.peaceful=0;g.mobs[0].training=0;g.mobs[0].spawnDef=-1;start(&g,3);g.mobs[0].hp=0;g.mobs[0].respawnAt=.01f;unsigned life=g.mobs[0].life;int sp=g.sp;combat_tick(&g,.05f,0,0);assert(g.mobs[0].life==life+1&&!combat_casting(&g)&&g.sp==sp);
 /* A saved pending cast contains only durable SP, and never resumes on load. */
 combat_init(&g,1500,1500,clear,NULL);dev_class_preset(&g,2);memset(g.mobs,0,sizeof(g.mobs));assert(skill_cast(&g,67,0,0));SavedCharacter a,b;unsigned char raw[SAVE_BYTES];save_capture(&a,&g,1);assert(save_valid(&a));save_encode(raw,&a);assert(save_decode(&b,raw)==1);Combat restored;save_restore(&restored,&b,1500,1500,clear,NULL);assert(!combat_casting(&restored)&&!restored.energyCoatLeft&&restored.sp==g.sp);
 printf("PASS37 %d timed/DEX/interrupt/resource/ground cases plus target-lock, respawn identity, blocked hit, overlap guards and transient Save20 restore\n",samples);
}
